head.b:skin:
:root{--p:@@P@@;--pd:@@PD@@;--g:@@G@@;--gh:@@GH@@;--ga:@@GA@@;--bg:@@BG@@;--tx:@@TX@@;--mu:@@MU@@;--ln:@@LN@@;--ft:@@FT@@}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{font-family:@@FONT_B@@;color:var(--tx);background:var(--bg);line-height:1.65;font-size:17px;-webkit-text-size-adjust:100%}
h1,h2,h3{font-family:@@FONT_H@@;line-height:1.2;margin:0 0 .5em;color:var(--p)}
a{color:var(--p)}
img{max-width:100%;display:block}
.hd{background:var(--p);color:#fff;text-align:center;padding:26px 18px 14px;border-bottom:4px double rgba(255,255,255,.6)}
.brand{display:inline-flex;align-items:center;gap:12px;color:#fff;text-decoration:none;font-family:@@FONT_H@@;font-size:28px;font-weight:700;line-height:1.1;text-align:left}
.brand svg{color:var(--ga);flex:none}
.brand img{height:46px;width:auto;max-width:120px;object-fit:contain;flex:none}
.brand small{display:block;font-family:Inter,sans-serif;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;opacity:.85;margin-bottom:4px}
.nav{display:flex;flex-wrap:wrap;justify-content:center;gap:6px 26px;margin-top:16px}
.nav a{color:#fff;text-decoration:none;font-size:15px;font-weight:500;padding:6px 2px;border-bottom:2px solid transparent;letter-spacing:.03em}
.nav a:hover{border-color:var(--ga)}
.hero{position:relative;color:#fff;text-align:center;padding:110px 22px;background:@@HERO_BG@@;border-bottom:6px double rgba(255,255,255,.55)}
.hero h1{color:#fff;font-size:clamp(32px,6vw,52px);text-shadow:0 2px 12px rgba(0,0,0,.3)}
.hero p{max-width:640px;margin:0 auto 26px;font-size:19px;opacity:.95}
.btn{display:inline-block;background:var(--g);color:#fff;text-decoration:none;padding:13px 28px;border-radius:999px;font-weight:600;font-size:16px}
.btn:hover{background:var(--gh)}
.btn.alt{background:var(--p)}
.wrap{max-width:1000px;margin:0 auto;padding:54px 22px}
.sec-t{text-align:center;font-size:32px}
.sec-s{text-align:center;color:var(--mu);margin:0 auto 34px;max-width:620px}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.cards>*,.two>*{min-width:0}
.card{background:#fff;border:1px solid var(--ln);border-top:4px solid var(--g);border-radius:10px;padding:26px 24px}
.card h3{font-size:22px}
.card p{margin:0 0 10px;color:var(--mu);font-size:16px}
.card b{color:var(--tx)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:center}
.one{display:block;max-width:720px;margin:0 auto}
.photo{width:100%;height:340px;object-fit:cover;border-radius:10px;border:1px solid var(--ln);box-shadow:0 10px 30px rgba(0,0,0,.14)}
.band{background:var(--p);color:#fff;text-align:center;padding:50px 22px;border-top:6px double rgba(255,255,255,.55)}
.band h2{color:#fff}
.band p{max-width:620px;margin:0 auto 22px;opacity:.95}
.band .btn{background:var(--ga);color:var(--pd)}
.page-h{background:#fff;border-bottom:1px solid var(--ln);text-align:center;padding:42px 22px 30px}
.page-h h1{font-size:38px;margin:0}
.page-h p{color:var(--mu);margin:6px 0 0}
table.hor{width:100%;border-collapse:collapse;background:#fff;border:1px solid var(--ln);border-radius:10px;overflow:hidden}
table.hor td{padding:16px 18px;border-bottom:1px solid var(--ln);vertical-align:top}
table.hor tr:last-child td{border-bottom:0}
table.hor td:first-child{font-weight:600;color:var(--p);white-space:nowrap}
table.hor small{display:block;color:var(--mu);font-size:14px}
.list{list-style:none;padding:0;margin:0}
.list li{padding:10px 0;border-bottom:1px solid var(--ln)}
.list li:last-child{border-bottom:0}
.list b{color:var(--p)}
.soc{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}
.soc a{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--ln);background:#fff;border-radius:999px;padding:8px 16px;text-decoration:none;font-size:14px;font-weight:500}
.ft{background:var(--ft);color:rgba(255,255,255,.78);text-align:center;padding:34px 22px;font-size:14px}
.ft a{color:var(--ga)}
.hid{display:none}
@media(max-width:820px){.cards{grid-template-columns:1fr}.two{grid-template-columns:1fr}.photo{height:260px}.hero{padding:70px 18px}.brand{font-size:23px}.sec-t{font-size:27px}}
@media(max-width:520px){.nav{gap:4px 16px}.nav a{font-size:14px}table.hor td{padding:12px}table.hor td:first-child{white-space:normal}.wrap{padding:40px 18px}}
.yt-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
@media(max-width:860px){.yt-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:560px){.yt-grid{grid-template-columns:minmax(0,1fr)}}
.yt-card{display:block;text-decoration:none;color:var(--tx);background:#fff;border:1px solid var(--ln);border-radius:12px;overflow:hidden}
.yt-card img{width:100%;aspect-ratio:16/9;object-fit:cover;background:#ddd}
.yt-card span{display:block;padding:12px 14px;font-weight:600;font-size:15px;line-height:1.4}
.yt-card:hover{border-color:var(--g)}
.yt-load,.yt-err{grid-column:1/-1;text-align:center;color:var(--mu)}
.an-card{max-width:760px;margin:0 auto;background:#fff;border:1px solid var(--ln);border-top:4px solid var(--g);border-radius:12px;padding:28px 30px}
.an-card h2{margin:0 0 4px}
.an-date{color:var(--mu);font-size:14px;margin:0 0 18px}
.an-body{overflow-wrap:anywhere;white-space:pre-line}
.an-body img{max-width:100%;height:auto;border-radius:8px}
.an-load,.an-empty{text-align:center;color:var(--mu);margin:0}
.an-form label{display:block;margin:0 0 16px;font-weight:600;color:var(--p);font-size:15px}
.an-form input,.an-form textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:12px 14px;border:1px solid var(--ln);border-radius:8px;font:inherit;font-weight:400;color:var(--tx);background:#fff}
.an-form textarea{resize:vertical}
.an-btns{display:flex;gap:12px;flex-wrap:wrap}
.an-btns button{cursor:pointer;font:inherit}
.btn-2{background:transparent;border:1px solid var(--p);color:var(--p);border-radius:8px;padding:12px 20px}
.an-msg{margin:14px 0 0;font-weight:600}.an-msg.ok{color:#2e7d32}.an-msg.err{color:#b3261e}
@@EXTRA_CSS@@

body.script:
//
(function(){var box=document.getElementById('yt-videos');if(!box)return;
var ch=box.getAttribute('data-channel');
var feed='https://www.youtube.com/feeds/videos.xml?playlist_id=UULF'+ch.slice(2);
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
fetch('https://api.rss2json.com/v1/api.json?rss_url='+encodeURIComponent(feed)).then(function(r){return r.json()}).then(function(j){
if(j.status!=='ok'||!j.items||!j.items.length)throw 0;var h='';
j.items.slice(0,6).forEach(function(i){var id=(i.link.split('v=')[1]||'').split('&')[0];
h+='<a class="yt-card" href="https://www.youtube.com/watch?v='+id+'" target="_blank" rel="noopener"><img loading="lazy" alt="" src="https://i.ytimg.com/vi/'+id+'/hqdefault.jpg"><span>'+esc(i.title)+'</span></a>'});
box.innerHTML=h}).catch(function(){box.innerHTML='<p class="yt-err">No pudimos cargar los videos ahora. Míralos directamente en nuestro canal de YouTube.</p>'})})();
//

//
(function(){
var DB='https://igle-site-default-rtdb.firebaseio.com';
var box=document.getElementById('anuncio'),form=document.getElementById('an-form');
var host=box||form;if(!host)return;
var ID=host.getAttribute('data-id');
function get(c){return fetch(DB+'/anuncios/'+ID+'/'+c+'.json').then(function(r){return r.json();});}
function load(){return Promise.all([get('titulo'),get('fecha'),get('texto')]).then(function(a){return {t:a[0],f:a[1],x:a[2]};});}
function el(tag,cls,txt){var e=document.createElement(tag);if(cls)e.className=cls;if(txt)e.textContent=txt;return e;}
function show(d){box.textContent='';if(!d||!d.t){box.appendChild(el('p','an-empty','No hay anuncios por el momento.'));return;}
box.appendChild(el('h2','',d.t));if(d.f)box.appendChild(el('p','an-date',d.f));if(d.x)box.appendChild(el('div','an-body',d.x));}
var KEY='an_'+ID;
if(box){var c=null;try{c=JSON.parse(sessionStorage.getItem(KEY));}catch(e){}
if(c&&Date.now()-c.ts<300000){show(c.d);}else{load().then(function(d){try{sessionStorage.setItem(KEY,JSON.stringify({ts:Date.now(),d:d}));}catch(e){}show(d);}).catch(function(){box.textContent='';box.appendChild(el('p','an-empty','No pudimos cargar el anuncio ahora.'));});}}
if(form){var msg=document.getElementById('an-msg');
function say(t,ok){msg.textContent=t;msg.className='an-msg '+(ok?'ok':'err');}
load().then(function(d){if(d&&d.t&&d.t.indexOf('No hay actividades')!==0){form.titulo.value=d.t||'';form.fecha.value=d.f||'';form.texto.value=d.x||'';}}).catch(function(){});
function send(t,f,x){var k=form.clave.value.trim();if(!k){say('Escribe tu clave.',false);return;}
say('Guardando…',true);
fetch(DB+'/anuncios/'+ID+'.json',{method:'PATCH',body:JSON.stringify({k:k,titulo:t,fecha:f,texto:x,actualizado:Date.now()})}).then(function(r){
if(r.ok){try{sessionStorage.removeItem(KEY);}catch(e){}say('Listo. Tu anuncio ya está publicado.',true);}
else if(r.status===401){say('La clave no es correcta.',false);}
else{say('No se pudo guardar. Revisa los datos e intenta de nuevo.',false);}
}).catch(function(){say('No hay conexión. Intenta de nuevo.',false);});}
form.addEventListener('submit',function(e){e.preventDefault();send(form.titulo.value.trim(),form.fecha.value.trim(),form.texto.value.trim());});
document.getElementById('an-quitar').addEventListener('click',function(){form.titulo.value='';form.fecha.value='';form.texto.value='';send('No hay actividades por el momento','','Pronto compartiremos nuestras próximas actividades.');});}
})();
//
